package fr.noxodev.noxoclaim.utils;
import org.bukkit.Location; import org.bukkit.entity.Player; import org.bukkit.plugin.java.JavaPlugin; import org.bukkit.scheduler.BukkitRunnable;
public final class TeleportTask extends BukkitRunnable {private final Player player;private final Location target;private final Location start;private int ticks;private final boolean cancelOnMove;public TeleportTask(JavaPlugin p,Player player,Location target,int seconds,boolean cancelOnMove){this.player=player;this.target=target;this.start=player.getLocation().clone();this.ticks=Math.max(0,seconds*20);this.cancelOnMove=cancelOnMove;runTaskTimer(p,0,1);}public void run(){if(!player.isOnline()||(cancelOnMove&&player.getLocation().distanceSquared(start)>0.04)){cancel();return;}if(ticks--<=0){player.teleport(target);cancel();}}}
